#### 2. NLP分析
```cpp
struct TokenizerParams {
    const string& text;
};

struct NLPAnalyzerResult {
    vector<string> keywords;       // 単語一覧
    double sentiment_score;           // 感化得点
};

class NLPAnalyzer {
private:
    vector<string> tokenize(const string& text) override {
        // 単語を tokenize します。この関数は、.split()や正規表現を活用します。
        vector<string> tokens;
        stringstream ss(text);
        string token;

        while (getline(ss, token, ' ')) {
            if (!token.empty()) {
                tokens.push_back(token);
            }
        }

        return tokens;
    }

    void extract_keywords(const vector<string>& tokens) override {
        // 単語一覧からTF-IDFを活用して keyword を抽出します。
        map<string, int> keywords;
        for (const auto& token : tokens) {
            ++keywords[token];
        }

        // 最大限のkeywordを抽出します。
        vector<string> top_keywords;
        for (auto& pair : keywords) {
            if (top_keywords.size() < 10 && !pair.first.empty()) { // 上位10件を抽出
                top_keywords.push_back(pair.first);
            }
        }

        keywords = move(top_keywords);
    }

public:
    NLPAnalyzer(const TokenizerParams& params) : tokenizer(params) {}

    vector<string> analyze(const string& text) override {
        // 単語 tokenize し、keywordを抽出します。
        vector<string> tokens = tokenize(text);
        extract_keywords(tokens);

        return keywords;
    }
};
```

