        log_file << "<div class='log-item'>";
        log_file << "<strong>["
            << get_current_time()
            << "] "
            << log.method
            << " (" 
            << log.parameter
            << ") "
            << log.description
            << "</strong></div>";
    }

    log_file << "</body></html>";
}
